CREATE TABLE "users" (
  "user_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "username" varchar(50) UNIQUE NOT NULL,
  "email" varchar(100) UNIQUE NOT NULL
);

CREATE TABLE "samples" (
  "sample_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "owner_id" integer NOT NULL,
  "name" varchar(100) NOT NULL,
  "length_seconds" decimal(10,2) NOT NULL,
  "bpm" integer,
  "file_format" varchar(10) NOT NULL,
  "upload_date" timestamp NOT NULL,
  "is_deleted" boolean NOT NULL DEFAULT false
);

CREATE TABLE "tags" (
  "tag_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(50) UNIQUE NOT NULL
);

CREATE TABLE "sample_tags" (
  "sample_id" integer NOT NULL,
  "tag_id" integer NOT NULL,
  PRIMARY KEY ("sample_id", "tag_id")
);

CREATE TABLE "ratings" (
  "rating_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer NOT NULL,
  "sample_id" integer NOT NULL,
  "rating" integer NOT NULL
);

CREATE TABLE "collections" (
  "collection_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "owner_id" integer NOT NULL,
  "name" varchar(100) NOT NULL
);

CREATE TABLE "collection_samples" (
  "collection_id" integer NOT NULL,
  "sample_id" integer NOT NULL,
  PRIMARY KEY ("collection_id", "sample_id")
);

CREATE UNIQUE INDEX ON "ratings" ("user_id", "sample_id");

ALTER TABLE "samples" ADD FOREIGN KEY ("owner_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "sample_tags" ADD FOREIGN KEY ("sample_id") REFERENCES "samples" ("sample_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "sample_tags" ADD FOREIGN KEY ("tag_id") REFERENCES "tags" ("tag_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "ratings" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "ratings" ADD FOREIGN KEY ("sample_id") REFERENCES "samples" ("sample_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "collections" ADD FOREIGN KEY ("owner_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "collection_samples" ADD FOREIGN KEY ("collection_id") REFERENCES "collections" ("collection_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "collection_samples" ADD FOREIGN KEY ("sample_id") REFERENCES "samples" ("sample_id") DEFERRABLE INITIALLY IMMEDIATE;
